params.command:
$ErrorActionPreference='Stop'
$repo='C:\Users\Xxkan\local-ai-workspaces\mhw-mods'
$wt='C:\Users\Xxkan\agent-worktrees\verify-pr166-d24d55'
$sha='d24d55a87ec38fc65b33976a53f6286d61d82b42'
git -C $repo fetch origin --prune
if(Test-Path $wt){git -C $repo worktree remove --force $wt 2>$null; Remove-Item -Recurse -Force $wt -ErrorAction SilentlyContinue}
git -C $repo worktree add --detach $wt $sha
try{
  dotnet restore "$wt\MhwModManager.sln"
  if($LASTEXITCODE -ne 0){throw 'restore failed'}
  dotnet build "$wt\MhwModManager.sln" -c Release --no-restore -m:1 -warnaserror
  if($LASTEXITCODE -ne 0){throw 'serial build failed'}
  dotnet test "$wt\MhwModManager.sln" -c Release --no-build --no-restore -m:1
  if($LASTEXITCODE -ne 0){throw 'serial test failed'}
  git -C $wt diff --check "$((git -C $wt merge-base origin/main HEAD).Trim())..HEAD"
  if($LASTEXITCODE -ne 0){throw 'diff check failed'}
  Write-Host "VERIFIED_SHA=$sha"
  Write-Host "SERIAL_BUILD=PASS"
  Write-Host "SOLUTION_TESTS=PASS"
} finally {
  git -C $repo worktree remove --force $wt 2>$null
}
